/**
 * THE CORRECTNESS GATE — the app's chart engine (Swiss Ephemeris WASM,
 * Moshier mode) is asserted against committed reference values produced with
 * the official Astrodienst Swiss Ephemeris C library 2.10.03 (native
 * binding `sweph`, real .se1 ephemeris files, flags SEFLG_SWIEPH|SEFLG_SPEED,
 * houses via swe_houses_ex2 hsys='P'=Placidus).
 *
 * Fixture provenance:
 *  - Reference values generated by scripts/generate-fixtures.mjs (see its
 *    header for the exact engine, files and flags). Regeneration is
 *    intentionally manual.
 *  - Positions are asserted within 0.01° and house cusps within 0.05°.
 *  - Independently of the reference engine, each fixture's SUN position is
 *    cross-anchored against NASA JPL Horizons
 *    (https://ssd.jpl.nasa.gov/horizons/, observer ephemeris quantity 31,
 *    Apparent geocentric ecliptic longitude equinox-of-date, which includes
 *    light-time, gravitational deflection, stellar aberration and nutation)
 *    — measured agreement is <= 0.0012 arc-minutes (max 0.00002°), recorded
 *    per fixture in crossCheckHorizons. No consumer astrology app was used
 *    for any expected value.
 *
 * The five documented charts span three decades, latitudes 64N..-36.8S and
 * a historical Estonian timezone offset (1961: Moscow time +03:00, before
 * DST existed in Estonia).
 */
import { beforeAll, expect, test } from 'vitest';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import './helpers/node-ephemeris-loader.js';
import { wasmFileUrl } from './helpers/node-ephemeris-loader.js';
import { computeChart, type Chart } from '../src/lib/chart';
import { validateStored, toBirthInput } from '../src/lib/storage';
import { resolveInstant, type BirthInput } from '../src/lib/time';

interface FixturePlanet { lon: number; speed: number }
interface Fixture {
  id: string;
  birth: {
    date: string; time: string; place: string; lat: number; lon: number;
    tz: string; offsetMinutes: number; utcInstant: string; eraNote: string;
  };
  julianDayUt: number;
  reference: {
    planets: Record<string, FixturePlanet>;
    houses: Record<string, number>;
  };
  crossCheckHorizons: { body: string; lonApparentEclipticOfDate: number; maxAbsDiffDeg: number };
}

const POS_TOL = 0.01;
const CUSP_TOL = 0.05;

const fixtures: Fixture[] = JSON.parse(
  readFileSync(path.join(import.meta.dirname, 'fixtures', 'natal-charts.json'), 'utf8'),
) as Fixture[];

function birthInputOf(f: Fixture): BirthInput {
  const [y, m, d] = f.birth.date.split('-').map(Number);
  const [hh, mm] = f.birth.time.split(':').map(Number);
  return {
    year: y!, month: m!, day: d!, hour: hh!, minute: mm!, timeUnknown: false,
    place: { lat: f.birth.lat, lon: f.birth.lon, tz: f.birth.tz },
  };
}

const charts = new Map<string, Chart>();
beforeAll(async () => {
  for (const f of fixtures) {
    // The fixture stores the storage schema; the same path the app uses.
    const stored = validateStored({
      schemaVersion: 1,
      date: (() => { const [y, m, d] = f.birth.date.split('-').map(Number); return { year: y!, month: m!, day: d! }; })(),
      time: (() => { const [h, min] = f.birth.time.split(':').map(Number); return { hour: h!, minute: min! }; })(),
      timeUnknown: false,
      place: { name: f.birth.place, lat: f.birth.lat, lon: f.birth.lon, tz: f.birth.tz },
    });
    expect(stored, `storage schema accepts ${f.id}`).not.toBeNull();
    const input = toBirthInput(stored!);
    const instant = resolveInstant(input);
    expect(instant, `instant resolves for ${f.id}`).not.toBeNull();
    charts.set(f.id, await computeChart(instant!, wasmFileUrl()));
  }
}, 120_000);

let maxPosDiff = 0;
let maxCuspDiff = 0;
let maxHorizonDiff = 0;

for (const f of fixtures) {
  test(`[${f.id}] time and timezone resolve to the documented UTC instant`, async () => {
    const { resolveInstant } = await import('../src/lib/time');
    const inst = resolveInstant(birthInputOf(f));
    expect(inst, 'instant exists').not.toBeNull();
    expect(inst!.offsetMinutes, `${f.id} local offset (IANA ${f.birth.tz})`).toBe(f.birth.offsetMinutes);
    // the documented instant, to the minute
    expect(inst!.utc.isoString.slice(0, 16)).toBe(f.birth.utcInstant.slice(0, 16));
  });

  test(`[${f.id}] JD UT matches the reference to 1e-9`, async () => {
    const chart = charts.get(f.id)!;
    expect(Math.abs(chart.julianDayUt - f.julianDayUt)).toBeLessThan(1e-9);
  });

  test(`[${f.id}] Sun independently agrees with NASA JPL Horizons within 0.01°`, async () => {
    const chart = charts.get(f.id)!;
    const sun = chart.placements.find((p) => p.body === 'sun')!;
    const horizon = f.crossCheckHorizons.lonApparentEclipticOfDate;
    const diff = Math.abs(sun.longitude - horizon);
    maxHorizonDiff = Math.max(maxHorizonDiff, diff);
    expect(diff, `${f.id} sun vs Horizons`).toBeLessThanOrEqual(POS_TOL);
  });

  test(`[${f.id}] planets + mean node within 0.01° of the C reference`, async () => {
    const chart = charts.get(f.id)!;
    for (const [name, ref] of Object.entries(f.reference.planets)) {
      const place = chart.placements.find((p) => p.body === name);
      expect(place, `${f.id} has ${name}`).toBeDefined();
      const diff = Math.abs(place!.longitude - ref.lon);
      maxPosDiff = Math.max(maxPosDiff, diff);
      expect(diff, `${f.id} ${name} longitude ${place!.longitude} vs ${ref.lon}`).toBeLessThanOrEqual(POS_TOL);
      const speedSignMatches = (place!.retrograde && ref.speed < 0) || (!place!.retrograde && ref.speed >= 0);
      expect(speedSignMatches, `${f.id} ${name} retrograde flag vs speed ${ref.speed}`).toBe(true);
    }
  });

  test(`[${f.id}] Placidus houses within 0.05° of the C reference`, async () => {
    const chart = charts.get(f.id)!;
    expect(chart.houses, `${f.id} houses computed`).not.toBeNull();
    for (let i = 1; i <= 12; i++) {
      const cusp = chart.houses!.find((c) => c.house === i)!;
      const ref = f.reference.houses['c' + i];
      const diff = Math.abs(cusp.cuspLongitude - ref);
      maxCuspDiff = Math.max(maxCuspDiff, diff);
      expect(diff, `${f.id} cusp ${i} ${cusp.cuspLongitude} vs ${ref}`).toBeLessThanOrEqual(CUSP_TOL);
    }
    const ascDiff = Math.abs(chart.ascendant!.longitude - f.reference.houses.asc);
    const mcDiff = Math.abs(chart.mediumCoeli!.longitude - f.reference.houses.mc);
    maxCuspDiff = Math.max(maxCuspDiff, ascDiff, mcDiff);
    expect(ascDiff, `${f.id} asc`).toBeLessThanOrEqual(CUSP_TOL);
    expect(mcDiff, `${f.id} mc`).toBeLessThanOrEqual(CUSP_TOL);
    // Ascendant must be house 1's cusp
    expect(chart.houses!.find((c) => c.house === 1)!.cuspLongitude).toBeCloseTo(chart.ascendant!.longitude, 6);
  });
}

test(`aggregate: engine deltas observed during the run stay tiny (positions<=0.01, cusps<=0.05, Horizons<=0.01)`, () => {
  expect(maxPosDiff).toBeLessThanOrEqual(POS_TOL);
  expect(maxCuspDiff).toBeLessThanOrEqual(CUSP_TOL);
  // Horizons vs Moshier-WASM measured agreement is at most 0.00002 deg,
  // asserted here against the same overall position tolerance
  expect(maxHorizonDiff).toBeLessThanOrEqual(POS_TOL);
});
